(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sq"] = {"ui":{"skip":"Kalo te përmbajtja","back":"← Kthehu te AI-gile","lang.button":"Gjuha: {name}","lang.dialog":"Zgjidh një gjuhë","lang.search":"Kërko gjuhë","lang.none":"Asnjë gjuhë nuk përputhet","lang.notYet":"{name} nuk është përkthyer ende","theme.aria":"Kalo mes temës së çelët dhe të errët","theme.toLight":"Kalo te tema e çelët","theme.toDark":"Kalo te tema e errët","index.title":"AI-gile: ekipi yt AI i zhvillimit, në një tabelë","index.description":"AI-gile është një tabelë kanban për ekipet e programimit me AI. Ata punojnë ndërsa ti fle; ti merr një grumbull të shkurtër gjërash për t'i vendosur, provuar dhe pranuar.","hero.logoAlt":"Ikona e tabelës AI-gile","hero.h1.html":"Ekipi yt AI i zhvillimit, në një&nbsp;tabelë.","hero.alpha":"🐣 Para-alfa e mbyllur","hero.alphaTitle":"E hershme dhe e papërfunduar: faleminderit që e provon!","hero.lede":"Ata ndërtojnë ndërsa ti fle. Zgjohesh me një grumbull të shkurtër: disa pyetje, disa gjëra për t'u provuar, një ose dy diamante vjollcë. Kliko, prano dhe kthehu te kafja.","dl.windows":"Aplikacioni për Windows","dl.browser":"Hape në shfletues","dl.soon":"Së shpejti","dl.notify":"🔔 Më njofto kur hapet","dl.notifySmall":"Alfa ose beta","hero.secondary":"Agjile, por ekipi nuk ka kurrë nevojë për kafen e mbledhjes së shkurtër. (Mbledhjet i bëjnë gjithsesi.)","pitch.h2":"AI-gile me sa fjalë të duash","pitch.lede":"Zgjidh një gjatësi, nga një fjalë deri në 144. Çdo gjatësi është përshkrim më vete, shkruar posaçërisht për të. Tërhiq rrëshqitësin ose përdor shigjetat.","pitch.rangeLabel":"Gjatësia në fjalë","pitch.dice":"🎲 version tjetër","pitch.words.one":"{n} fjalë","pitch.words.other":"{n} fjalë","pitch.letters.one":"{n} shkronjë","pitch.letters.other":"{n} shkronja","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karaktere","count.line.html.one":"{n} kartë është tani në tabelë","count.line.html.other":"{n} karta janë tani në tabelë","features.aria":"Çfarë bën","f.pile.h":"Një grumbull për ty","f.pile.html":"<b>Për ty</b> mbledh gjithçka që të pret, nga të gjitha projektet: pyetje, gjëra për t'u provuar, detyra që i bën vetëm një njeri. Radha jote të tregon çfarë vjen më pas dhe sa zgjat.","f.sleep.h":"Ekipe që punojnë ndërsa ti fle","f.sleep.p":"Çdo projekt ka një drejtues dhe një ekip agjentësh AI. Shkruaj një koment te karta dhe ekipi zgjohet, bën punën dhe ta kthen me hapa që i ndjek edhe një njeri i lodhur.","f.tester.h":"Fillimisht kontrollon një testues AI","f.tester.p":"Para se të të vijë diçka, testuesi ndjek hapat në një kopje të aplikacionit dhe tregon çfarë pa, me një pamje ekrani. Shfletoji ato që kaluan dhe prano me një klik.","f.proof.h":"Prova, jo premtime","f.proof.p":"Çdo dorëzim tregon çfarë ndryshoi: skedarët, ndryshimet, pamjet e ekranit. S'ke nevojë të hapësh çdo aplikacion për të parë nëse u krye.","f.chat.h":"Bisedo me drejtuesit e tu","f.chat.p":"Një shirit si në Discord: një ikonë për projekt, diamante vjollcë për atë që të do ty. Shkruaji drejtuesit një ide; ai e kthen në karta dhe plan, me një buton ✅ Shko.","f.tidy.h":"E mban vetë rendin","f.tidy.p":"Kartat e ngjashme bashkohen, titujt e ngatërruar rregullohen dhe një kontroll tokenësh e mban kodin të hollë. Më pak gjëra për të ndërruar, më pak për të menduar.","f.private.h":"I yti, në kompjuterin tënd","f.private.li1":"Tabela punon në kompjuterin tënd dhe i përgjigjet vetëm ty.","f.private.li2":"Mesazhet private mes njerëzve janë të enkriptuara nga skaji në skaj.","f.private.li3":"Pa llogari, pa gjurmues, pa cookies.","f.lang.h":"Në gjuhën tënde","f.lang.p":"Mbi 120 gjuhë, nga holandishtja, uellsishtja dhe japonishtja te piratët, Yoda dhe klingonishtja, me kalim të shpejtë në anglisht për fjalët e zhvilluesve.","tl.aria":"Kronologjia nga biseda e parë te plani","tl.h2":"Nga biseda e parë te ajo që vjen më pas","tl.lede":"Data dhe orë të vërteta, në zonën tënde kohore. Pas sot është plan, pa data të premtuara.","tl.today":"Sot","tl.planned":"e planifikuar","tl.cards.one":"{n} kartë","tl.cards.other":"{n} karta","join.h2":"Bashkohu","join.lede":"AI-gile po ndërtohet nga një njeri i vogël dhe shumë agjentë të durueshëm. Tani për tani është private, në alfa të mbyllur me miq. Do ta provosh kur të hapet?","join.btn":"Shpreh interes","join.small":"Do të shkruajmë me email, asgjë tjetër","footer.tag":"AI-gile. Pa gjurmues, pa cookies, pa kafe mbledhjeje.","footer.licence":"Licenca e biznesit","footer.status":"Gjendja","form.sending":"Po dërgohet…","form.failed":"Nuk funksionoi: provo përsëri më vonë.","form.offline":"Nuk u arrit AI-gile: provo përsëri më vonë.","interest.title":"AI-gile: më njofto kur hapet alfa","interest.description":"Lër emailin për të mësuar kur hapet alfa ose beta e mbyllur e AI-gile.","interest.h1":"🔔 Më njofto kur hapet","interest.lede":"AI-gile është në para-alfa të mbyllur. Lër emailin dhe do të të shkruajmë një herë, kur të ketë vend për ty.","interest.email":"Emaili yt","interest.which":"Cili test?","interest.alpha":"Alfa e mbyllur: e hershme, e ashpër, plot ndryshime","interest.beta":"Beta: më e qëndrueshme, më vonë","interest.both":"Cilado, cila të vijë e para","interest.submit":"Më shto në listë","interest.thanks":"Faleminderit! Je në listë.","interest.kept":"Ruhen vetëm emaili yt dhe testi që zgjodhe, vetëm për këtë listë. Pa buletin, pa gjurmues.","licence.title":"AI-gile: licenca e biznesit","licence.description":"E përdor AI-gile në biznesin tënd? Apliko për një licencë biznesi falas.","licence.h1":"📜 Licenca e biznesit","licence.lede":"E përdor AI-gile në punë? Na trego kush je dhe çfarë bën. Nëse sjell diçka të mirë, licenca është falas.","licence.company":"Kompania","licence.website":"Faqja e internetit","licence.what":"Çfarë bën","licence.how":"Si ndihmon botën","licence.email":"Emaili","licence.submit":"Apliko","licence.thanks":"Faleminderit! Do të përgjigjemi me email.","status.title":"Gjendja e AI-gile","status.h1":"Gjendja e AI-gile","status.quiet":"Gjithçka e qetë","status.checking":"Po kontrollohet…","status.offline":"Shërbimi i gjendjes nuk arrihet tani (po provoj përsëri)","status.updated":"përditësuar {ago}","status.justNow":"tani fill","status.min":"{n} min më parë","status.hours":"{n} orë më parë","status.days":"{n} ditë më parë","live.h2":"Shikoje duke u ndërtuar, drejtpërdrejt","live.caption":"Çdo kartë është e fshehur: sheh formën e punës, jo fjalët.","live.watching.one":"drejtpërdrejt: {n} po shikon","live.watching.other":"drejtpërdrejt: {n} po shikojnë","live.offline":"Tabela drejtpërdrejt po merr pak pushim. Kthehu së shpejti.","live.cols":"Backlog|Për t'u bërë|Në punë|Ekipi po kontrollon|Për ty ta testosh|Për ekipin|Kryer"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotë.","Deleguar."]},{"n":2,"texts":["Kanban robotësh.","Agjentët punojnë.","Idetë ndërtohen."]},{"n":3,"texts":["Kanban për robotë.","Idetë bëhen funksione.","Kanban falas agjentësh."]},{"n":5,"texts":["Tabelë kanban e drejtuar nga agjentë.","Ti shkruan karta. Agjentët ndërtojnë.","Falas, lokale, testuar, pak çudi."]},{"n":8,"texts":["Një tabelë kanban falas ku punojnë agjentë AI.","Shkruaj një ide. Agjentët e ndërtojnë. Ti e pranon.","Agjilitet për një njeri dhe shumë robotë të durueshëm."]},{"n":13,"texts":["Një tabelë kanban në kompjuterin tënd ku kartat i marrin agjentët AI e punojnë.","Shkruaj një ide. Një ekip agjentësh e ndërton. Një testues e kontrollon. Ti thua po.","Falas, pa llogari e pa gjurmues: një tabelë, disa robotë dhe ti ke fjalën."]},{"n":21,"texts":["AI-gile është një tabelë kanban për të punuar me agjentë AI që programojnë. Ata marrin kartat; ti i teston dhe i pranon.","Çdo projekt ka një drejtues dhe një ekip agjentësh AI. Shkruaj koment te çdo kartë dhe ekipi nis punën.","Një tabelë personale detyrash, falas, që punon në kompjuterin tënd. Punëtorët janë robotë. Ai që thotë po je ti."]},{"n":34,"texts":["Ti vë idetë në tabelë. Një ekip agjentësh AI i kthen në funksione që punojnë, i teston dhe ta kthen me hapa për t'i provuar. Asgjë nuk quhet e kryer derisa ta thuash ti.","AI-gile është një tabelë kanban e bërë në shtëpi, që Rich e ndërtoi me shumë ndihmë nga agjentët që tani i drejton vetë. Është falas, punon në kompjuterin tënd dhe ndahet me miqtë, nuk shitet.","Imagjino një tabelë kanban të zakonshme, me kolona nga Backlog te Kryer, vetëm se kartat i marrin agjentë AI. Raportojnë përparimin, pyesin kur ngecin dhe gjithmonë presin miratimin tënd."]},{"n":55,"texts":["AI-gile është një tabelë kanban ku ekipi përbëhet nga agjentë AI. Çdo projekt ka një drejtues që planifikon punën dhe ndihmës që e ndërtojnë. Kur një funksion është gati, një testues AI e provon dhe merr një pamje ekrani, pastaj ai bie në grumbullin tënd. Pranoje, ose shkruaj koment dhe ata e ripunojnë.","Nisi si mënyra e një njeriu për të ndjekur shumë seanca programimi me AI njëkohësisht, dhe u rrit në një tabelë të vërtetë. Punon në kompjuterin tënd, nuk kërkon llogari dhe nuk ka gjurmues. Është falas për miqtë dhe të kureshtarët. Është edhe e papërfunduar, ndaj prit skaje të ashpra dhe ndonjë befasi.","Ja versioni i sinqertë. Idetë duhet t'i kesh prapë ti, dhe rezultatet duhet t'i kontrollosh prapë ti. AI-gile bën gjithçka në mes: i mban kartat në rregull, zgjon agjentin e duhur kur komenton, tregon saktësisht çfarë ndryshoi dhe i vë të gjitha në një grumbull të shkurtër për ty."]},{"n":89,"texts":["AI-gile është një tabelë kanban falas që e ekzekuton në kompjuterin tënd. Në vend të njerëzve, çdo projekt ka një ekip agjentësh AI: një drejtues që idetë e tua i kthen në karta dhe plan, dhe ndihmës që i marrin kartat sipas përparësisë. Kur diçka është ndërtuar, një testues AI ndjek hapat e testit dhe të tregon çfarë pa. Pastaj pret në një grumbull me emrin Për ty. Ti e pranon, ose komenton dhe ekipi provon përsëri. Asgjë nuk arrin te Kryer pa ty.","Disa gjëra që mund të mos i presësh. Një roje nate e mbush kolonën Për t'u bërë ndërsa ti fle, duke zgjedhur karta që nuk kanë nevojë për përgjigje nga ti. Një numërues tokenësh tregon sa kanë përdorur agjentët sot dhe këtë javë, dhe Modaliteti pa tokenë u thotë të ndalojnë shpenzimin. Mund t'u shkruash miqve, dhe mesazhet private janë të enkriptuara nga skaji në skaj. Tabela flet rreth 120 gjuhë, përfshirë holandisht, flamandisht, piratësh dhe klingonisht. Asgjë nga kjo nuk kushton asnjë qindarkë, dhe askush nuk po përpiqet të ta shesë.","AI-gile është një projekt i vogël personal, jo kompani. Rich donte të kujdesej për disa projekte programimi me AI pa hapur çdo aplikacion për t'i kontrolluar, ndaj ai dhe agjentët ndërtuan një tabelë për këtë, pastaj me të ndërtuan pjesën tjetër të saj. Është në para-alfa të mbyllur, që do të thotë se punon, më së shumti, për një grusht miqsh. Nuk ka faqe çmimesh, buletin dhe as plan rritjeje. Nëse të duket e dobishme, mund të kërkosh ta provosh kur të hapet pak më shumë."]},{"n":144,"texts":["AI-gile është një tabelë kanban për një njeri dhe shumë agjentë AI. Punon në kompjuterin tënd dhe është plotësisht falas. Shton projekte dhe secili merr një drejtues dhe një ekip të vogël. Bisedon me drejtuesin, pak si në Discord, dhe përshkruan një ide; drejtuesi e kthen në karta dhe plan, pastaj pret që ti të shtypësh Shko. Ekipi i kalon kartat sipas përparësisë, me një rresht komandash të thjeshtë të bërë për modelet gjuhësore. Para se diçka të të kthehet, një testues AI ndjek hapat në një kopje të aplikacionit dhe bashkëngjit një pamje ekrani. Puna e përfunduar bie në grumbullin tënd me skedarët e ndryshuar dhe ndryshimet. Ti e pranon, ose lë një koment dhe ekipi zgjohet e provon përsëri. Vetëm ti mund ta kalosh një kartë te Kryer.","Një ditë me AI-gile, përafërsisht. Në mbrëmje lë disa komente: ky buton është në vendin e gabuar, ajo listë duhet renditur, mund të kemi një temë të errët. Shkon të flesh. Agjentët i lexojnë komentet, bëjnë ndryshimet, i testojnë dhe ta kthejnë punën. Nëse Për t'u bërë mbaron, roja e natës e mbush nga backlog me karta që nuk kanë nevojë për përgjigje nga ti. Në mëngjes ka një grumbull të shkurtër: disa pyetje dhe disa gjëra për t'u provuar, secila me hapa që i ndjek edhe një njeri i përgjumur dhe me një pamje ekrani që punon. I kalon një nga një, pranon të mirat dhe kthen të tjerat. Numëruesi i tokenëve tregon sa shpenzoi gjithçka, dhe Modaliteti pa tokenë është për javët e pakta. Pastaj ha mëngjes, ku agjentët ende nuk mund të ndihmojnë.","Së pari, çfarë nuk është AI-gile. Nuk është startup, nuk shitet dhe askush nuk mbledh të dhënat e tua. Është një tabelë falas që punon në kompjuterin tënd, pa llogari, pa gjurmues dhe pa cookies. Çfarë është: një vend i rregullt për të parë të gjitha projektet e programimit me AI njëherësh, me një ekip agjentësh që bëjnë kartat dhe ti që merr vendimet. Bashkon kartat e ngjashme, rregullon titujt e ngatërruar dhe vëzhgon që kodi të mbetet i hollë. Flet rreth 120 gjuhë, nga holandishtja dhe flamandishtja te piratët dhe klingonishtja. Miqtë mund t'i shkruajnë njëri-tjetrit privatisht dhe të enkriptuar. E ndërtoi Rich me një numër të madh agjentësh të durueshëm, kryesisht duke përdorur vetveten. Është në para-alfa të mbyllur, ndaj në disa vende është e ashpër. Nëse të tingëllon argëtuese, kërko me mirësi dhe mund të hysh herët."]}],"quips":{"1":"Një fjalë. E guximshme. Ndoshta tepër.","3":"Tri fjalë. Tashmë më të sinqerta se shumica e faqeve të produkteve.","8":"Tetë fjalë. Prapë më të shkurtra se një mbledhje e shkurtër.","21":"Gjatësitë janë story points, meqë ra fjala. Natyrisht që janë.","55":"Pesëdhjetë e pesë fjalë. Dy karta u kryen ndërsa lexoje.","144":"Kjo është e gjata. Nuk ka 233. Agjentët kanë shkuar të flenë."}},"timeline":{"first-idea.name":"Ideja e parë","first-idea.line":"Biseda e parë, para se të ekzistonte ndonjë kod.","first-board.name":"Tabela e parë","first-board.line":"Një tabelë që ndjek ndërtimin e vet: karta, kolona, tërhiq e lësho, projekte.","team-roles.name":"Ekipi dhe rolet","team-roles.line":"Profile agjentësh, shabllone ekipesh, hapësira dhe kush bën çfarë.","install.name":"Instalimi dhe versionet","install.line":"Një zip që e instalon edhe një mik, vetëpërditësime, kanale dhe kthim prapa.","usage-saver.name":"Kursimi i përdorimit","usage-saver.line":"Mat sa kushtojnë ekzekutimet, mbaje kodin të hollë, kurse kufirin tënd.","friends.name":"Miqtë dhe ndarja","friends.line":"Mesazhe private, një rele e kodifikuar, ftesa, role dhe projekte të përbashkëta.","languages.name":"Gjuhët","languages.line":"Çdo tekst ekrani në një skedar gjuhe, me holandishten dhe flamandishten të parat.","ai-tester.name":"Testuesi AI","ai-tester.line":"Një testues kontrollon çdo dorëzim i pari dhe tregon çfarë pa.","website.name":"Faqja e internetit","website.line":"aigile.lol, parapamja dhe kjo kronologji.","streaming.name":"Biseda dhe transmetimi","streaming.line":"Discord, Twitch, OBS, modaliteti i transmetuesit, GIF-e dhe emoji.","no-ai.name":"Edicioni pa AI","no-ai.line":"Një tabelë për njerëzit që programojnë pa AI, dhe tabela publike.","night-watch.name":"Roja e natës","night-watch.line":"Një rojtar dhe Scrum Master i mbajnë ekipet në punë ndërsa ti fle.","p-more.name":"Gjithçka tjetër","p-more.line":"Ide më të vogla që presin radhën.","p-android.name":"Telefoni dhe Android","p-android.line":"Arrije tabelën nga telefoni, pastaj një aplikacion Android vendas.","p-release.name":"Alfa e më tej","p-release.line":"Alfa e mbyllur, faqja e gjallë, pastaj beta.","p-languages.name":"Më shumë gjuhë","p-languages.line":"Mbi njëqind gjuhë dhe një mënyrë zhytjeje për ata që mësojnë.","p-engines.name":"Më shumë motorë AI","p-engines.line":"Zgjidh Claude, Codex ose Gemini për çdo agjent.","p-pro.name":"Praktikë profesionale","p-pro.line":"Etiketa rreziku, porta bashkimi, karta incidentesh dhe parapete.","p-self.name":"Kujdesi për ty","p-self.line":"Modaliteti i lodhjes, kujtesa për kujdesin ndaj vetes dhe 4:20.","p-servers.name":"Serverët dhe rritja","p-servers.line":"Cilësime globale serveri, role dhe planifikim për rritje.","p-livestream.name":"Shtesa transmetimi","p-livestream.line":"Biseda e Twitch, emoji të personalizuara dhe një pamje e gjallë publike."}};
